select

from orders


        and user_id = #{userId}


        and status = #{status}


        and status in

            #{s}



        and number like concat('%', #{number}, '%')


        and order_time >= #{beginTime}


        and order_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)


order by order_time desc, id desc

select

from orders
where status = #{status} and order_time < #{orderTime}

select DATE_FORMAT(order_time, '%Y-%m-%d') as day,
sum(amount) as value
from orders
where status = #{status}
and order_time >= #{begin}
and order_time < #{endExclusive}
group by day

select od.name name, sum(od.number) as value from order_detail od, orders o where od.order_id = o.id and o.status = 5
and order_time >= #{begin}
and order_time < #{endExclusive}
group by name order by value desc limit 0, 10

